/**
 * Radioactive Decay simulation.
 *
 * lambda = ln(2) / T_half
 * N(t) = N0 * (1/2)^(t / T_half) = N0 * e^(-lambda*t)
 * activity(t) = lambda * N(t)
 *
 * Unlike every other time-based lab here (Circular Motion, Simple Harmonic
 * Motion, Orbital Motion -- all periodic), N(t) never returns to an earlier
 * value: it only ever decreases, approaching but never reaching zero.
 * remaining + decayed always equals the initial count. Always computed
 * here, in code -- never fetched from a server and never generated by AI.
 * Mirrors apps/physics/simulations_radioactive_decay.py exactly (same
 * bounds, same formulas). This file owns its own physics, SVG and
 * controls; it shares only the run-loop/registry shell in lab.js.
 */
(function (window, document) {
  "use strict";

  var MIN_INITIAL_COUNT = 100.0;
  var MAX_INITIAL_COUNT = 10000.0;
  var MIN_HALF_LIFE_S = 1.0;
  var MAX_HALF_LIFE_S = 20.0;
  var MAX_TIME_S = 60.0;

  function clampInitialCount(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_INITIAL_COUNT, Math.min(MAX_INITIAL_COUNT, n));
  }
  function clampHalfLife(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_HALF_LIFE_S, Math.min(MAX_HALF_LIFE_S, n));
  }

  function computeState(initialCount, halfLife, t) {
    var n0 = clampInitialCount(initialCount);
    var halfLifeS = clampHalfLife(halfLife);
    t = Math.max(0, Math.min(MAX_TIME_S, Number(t)));
    var decayConstant = Math.log(2) / halfLifeS;
    var halfLivesElapsed = t / halfLifeS;
    var remaining = n0 * Math.pow(0.5, halfLivesElapsed);
    var decayed = n0 - remaining;
    var activity = decayConstant * remaining;
    return {
      remaining: remaining,
      decayed: decayed,
      remainingFraction: remaining / n0,
      activity: activity,
      halfLivesElapsed: halfLivesElapsed
    };
  }

  var STEP_S = 0.2;
  var REDUCED_MOTION_STOP_S = 6;

  function readNum(el, name, fallback) {
    var raw = el.getAttribute("data-" + name);
    var value = parseFloat(raw);
    return isFinite(value) ? value : fallback;
  }
  function round4(n) {
    return Math.round(n * 10000) / 10000;
  }

  function createDecaySim(root, config, lab) {
    var state = {
      initialCount: clampInitialCount(readNum(root, "initial-count", 1000)),
      halfLife: clampHalfLife(readNum(root, "half-life", 5)),
      timeS: 0,
      remaining: 0,
      decayed: 0,
      remainingFraction: 1,
      activity: 0
    };

    var trace = []; // [t, remaining] samples, feeds the N(t) decay curve
    var maxN = 1;

    var el = {
      levelRemaining: root.querySelector("[data-level-remaining]"),
      levelDecayed: root.querySelector("[data-level-decayed]"),
      sceneDesc: root.querySelector("[data-scene-desc]"),
      scene: root.querySelector("[data-lab-scene]"),
      sceneStatus: root.querySelector("[data-scene-status]"),
      graph: root.querySelector("[data-lab-graph]"),
      graphDesc: root.querySelector("[data-graph-desc]"),
      trace: root.querySelector("[data-lab-trace]"),
      valueInitial: root.querySelector("[data-value-initial]"),
      valueHalfLife: root.querySelector("[data-value-half-life]"),
      valueTime: root.querySelector("[data-value-time]"),
      valueRemaining: root.querySelector("[data-value-remaining]"),
      valueDecayed: root.querySelector("[data-value-decayed]"),
      valueActivity: root.querySelector("[data-value-activity]"),
      eqRemaining: root.querySelector("[data-eq-remaining]"),
      eqActivity: root.querySelector("[data-eq-activity]"),
      outInitial: root.querySelector("[data-out-initial]"),
      outHalfLife: root.querySelector("[data-out-half-life]"),
      inputInitial: root.querySelector("[data-input-initial]"),
      inputHalfLife: root.querySelector("[data-input-half-life]"),
      btnStart: root.querySelector("[data-action-start]"),
      btnPause: root.querySelector("[data-action-pause]"),
      btnReset: root.querySelector("[data-action-reset]"),
      btnStep: root.querySelector("[data-action-step]"),
      inputTime: root.querySelector("[data-input-time]"),
      outTime: root.querySelector("[data-out-time]"),
      motionNote: root.querySelector("[data-motion-note]")
    };

    var loop = lab.createRunLoop(tick, {});

    function recordTrace() {
      trace.push([round4(state.timeS), round4(state.remaining)]);
      // Bound memory for a long-running loop -- keep the most recent window.
      if (trace.length > 2000) trace.shift();
    }

    function setInitialCount(value) {
      state.initialCount = clampInitialCount(value);
      maxN = state.initialCount;
      if (el.inputInitial) el.inputInitial.value = String(state.initialCount);
      if (el.outInitial) el.outInitial.textContent = String(state.initialCount);
      setTime(0);
    }
    function setHalfLife(value) {
      state.halfLife = clampHalfLife(value);
      if (el.inputHalfLife) el.inputHalfLife.value = String(state.halfLife);
      if (el.outHalfLife) el.outHalfLife.textContent = String(state.halfLife);
      setTime(0);
    }

    function start() {
      loop.start();
    }
    function pause() {
      loop.stop();
    }
    function reset() {
      loop.stop();
      setTime(0);
    }

    function rebuildTrace(upToT) {
      trace = [];
      var sampleDt = Math.max(upToT / 60, 0.1);
      for (var t = 0; t < upToT - 1e-9; t += sampleDt) {
        var c = computeState(state.initialCount, state.halfLife, t);
        trace.push([round4(t), round4(c.remaining)]);
      }
      trace.push([round4(upToT), round4(state.remaining)]);
    }

    function setTime(value) {
      loop.stop();
      var t = Number(value);
      if (!isFinite(t)) return;
      t = Math.max(0, Math.min(MAX_TIME_S, t));
      var computed = computeState(state.initialCount, state.halfLife, t);
      state.timeS = t;
      state.remaining = computed.remaining;
      state.decayed = computed.decayed;
      state.remainingFraction = computed.remainingFraction;
      state.activity = computed.activity;
      rebuildTrace(t);
      if (el.sceneStatus) el.sceneStatus.textContent = "";
      render();
    }

    function stepForward() {
      setTime(state.timeS + STEP_S);
    }

    function tick(dt) {
      if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        if (el.sceneStatus) {
          el.sceneStatus.textContent = "Reached the end of the simulated time window (60 s).";
        }
        return;
      }
      var nextT = Math.min(MAX_TIME_S, state.timeS + dt);
      var computed = computeState(state.initialCount, state.halfLife, nextT);
      state.timeS = nextT;
      state.remaining = computed.remaining;
      state.decayed = computed.decayed;
      state.remainingFraction = computed.remainingFraction;
      state.activity = computed.activity;
      recordTrace();

      if (loop.reduced && state.timeS >= REDUCED_MOTION_STOP_S) {
        loop.stop();
      }
      render();
    }

    function renderScene() {
      var pct = Math.max(0, Math.min(1, state.remainingFraction));
      var barH = 140;
      var remainingH = pct * barH;
      if (el.levelRemaining) {
        el.levelRemaining.setAttribute("y", String(190 - remainingH));
        el.levelRemaining.setAttribute("height", String(remainingH));
      }
      if (el.levelDecayed) {
        el.levelDecayed.setAttribute("y", String(190 - barH));
        el.levelDecayed.setAttribute("height", String(barH - remainingH));
      }
      var text =
        "A sample that started with " + state.initialCount.toFixed(0) + " atoms and a half-life of " +
        state.halfLife.toFixed(1) + " seconds. At " + state.timeS.toFixed(1) + " seconds, " +
        state.remaining.toFixed(1) + " remain and " + state.decayed.toFixed(1) + " have decayed.";
      if (el.scene) el.scene.setAttribute("aria-label", text);
      if (el.sceneDesc) el.sceneDesc.textContent = text;
    }

    function renderGraph() {
      if (!el.trace) return;
      var w = 348, h = 156, left = 40, top = 10, bottom = 6;
      var tMin = trace.length ? trace[0][0] : 0;
      var tMax = Math.max(tMin + 1, state.timeS);
      var yMax = Math.max(1, maxN);
      var points = [];
      for (var i = 0; i < trace.length; i++) {
        var px = left + ((trace[i][0] - tMin) / (tMax - tMin)) * (w - left - 12);
        var py = top + (1 - trace[i][1] / yMax) * (h - top - bottom);
        points.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      el.trace.setAttribute("points", points.join(" "));
      var graphText =
        "Remaining count versus time. At " + state.timeS.toFixed(1) + " seconds, " +
        state.remaining.toFixed(1) + " atoms remain out of " + state.initialCount.toFixed(0) + ".";
      if (el.graph) el.graph.setAttribute("aria-label", graphText);
      if (el.graphDesc) el.graphDesc.textContent = graphText;
    }

    function render() {
      if (el.valueInitial) el.valueInitial.textContent = state.initialCount.toFixed(0);
      if (el.valueHalfLife) el.valueHalfLife.textContent = state.halfLife.toFixed(1);
      if (el.valueTime) el.valueTime.textContent = state.timeS.toFixed(2);
      if (el.valueRemaining) el.valueRemaining.textContent = state.remaining.toFixed(1);
      if (el.valueDecayed) el.valueDecayed.textContent = state.decayed.toFixed(1);
      if (el.valueActivity) el.valueActivity.textContent = state.activity.toFixed(2);
      if (el.eqRemaining) el.eqRemaining.textContent = state.remaining.toFixed(1);
      if (el.eqActivity) el.eqActivity.textContent = state.activity.toFixed(2);
      if (el.inputTime && document.activeElement !== el.inputTime) {
        el.inputTime.value = String(round4(state.timeS));
      }
      if (el.outTime) el.outTime.textContent = state.timeS.toFixed(1);
      renderScene();
      renderGraph();
      root.dispatchEvent(new CustomEvent("lab:state", { detail: getState() }));
    }

    function getState() {
      return {
        initialCount: state.initialCount,
        halfLifeS: state.halfLife,
        timeS: state.timeS,
        remainingCount: state.remaining,
        decayedCount: state.decayed,
        activityPerS: state.activity,
        running: loop.isRunning()
      };
    }

    if (el.inputInitial) {
      el.inputInitial.addEventListener("input", function () { setInitialCount(el.inputInitial.value); });
      el.inputInitial.addEventListener("change", function () { setInitialCount(el.inputInitial.value); });
    }
    if (el.inputHalfLife) {
      el.inputHalfLife.addEventListener("input", function () { setHalfLife(el.inputHalfLife.value); });
      el.inputHalfLife.addEventListener("change", function () { setHalfLife(el.inputHalfLife.value); });
    }
    if (el.btnStart) el.btnStart.addEventListener("click", start);
    if (el.btnPause) el.btnPause.addEventListener("click", pause);
    if (el.btnReset) el.btnReset.addEventListener("click", reset);
    if (el.btnStep) el.btnStep.addEventListener("click", stepForward);
    if (el.inputTime) {
      el.inputTime.addEventListener("input", function () { setTime(el.inputTime.value); });
      el.inputTime.addEventListener("change", function () { setTime(el.inputTime.value); });
    }

    if (loop.reduced && el.motionNote) el.motionNote.hidden = false;

    maxN = state.initialCount;
    reset();

    var api = {
      setInitialCount: setInitialCount,
      setHalfLife: setHalfLife,
      start: start,
      pause: pause,
      reset: reset,
      setTime: setTime,
      step: stepForward,
      getState: getState
    };
    root.labInstance = api;
    return api;
  }

  PhysicsLab.register("radioactive_decay", createDecaySim);

  PhysicsLab.RadioactiveDecay = {
    MIN_INITIAL_COUNT: MIN_INITIAL_COUNT,
    MAX_INITIAL_COUNT: MAX_INITIAL_COUNT,
    MIN_HALF_LIFE_S: MIN_HALF_LIFE_S,
    MAX_HALF_LIFE_S: MAX_HALF_LIFE_S,
    MAX_TIME_S: MAX_TIME_S,
    clampInitialCount: clampInitialCount,
    clampHalfLife: clampHalfLife,
    computeState: computeState
  };
})(window, document);
